-- Ciornă a paginii de pornire, reconstruită după homepage-ul de pe Shopify (reduxio.ro): bandă text, hero, "Bun venit",
-- grila "Reduceri BLACK FRIDAY" cu cele 7 produse, footer comun. Pagina e pusă pe domeniul comanda.reduxio.ro, lățime "largă",
-- marcată ca pagină de pornire, dar ca CIORNĂ: nu se vede pe domeniu până nu o publici din editor.
-- Rulează-l o singură dată, după migrarea 099. Prețurile sunt cele din Shopify la momentul citirii; verifică-le.
-- Linkurile /goodsleep, /herbazen, /turmident, /inel-magnifit trebuie să existe ca pagini pe domeniu (acum există doar /slimgel).
insert into landing_page_content (organization_id, domain_id, slug, title, background, blocks, status, is_home, layout)
select d.organization_id, d.id, 'acasa', 'Reduxio', '#ffffff', $json$[{"type":"topbar","mode":"scroll","text":"","messages":["PLATA LA LIVRARE","REDUCERI PÂNĂ LA 90%","LIVRARE ÎN 1-2 ZILE"],"effect":"marquee","speed":"medium","size":16,"sticky":false,"href":null,"bg":"#000000","color":"#ffffff","label":"Bandă text"},{"type":"image","src":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/header_q70.webp?v=1793191877","alt":"Reduxio","width":1080,"height":1350,"radius":0,"inset":0,"maxWidth":560,"href":null,"label":"Hero"},{"type":"html","html":"<div style=\"text-align:center;padding:14px 12px\"><span style=\"display:inline-block;background:#e9ff0e;border-radius:20px;padding:10px 20px;font-weight:700;font-size:18px;color:#111\">Bun venit la Reduxio</span></div>","label":"Bun venit"},{"type":"products","title":"Reduceri BLACK FRIDAY","items":[{"image":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/img4.jpg?v=1791146345","width":600,"height":600,"title":"SlimGel - Gel pentru slăbit și anti-celulită","price":"68 lei","oldPrice":"168 lei","badge":"Cel mai vândut","badgeBg":"#e9ff0e","badgeColor":"#000000","href":"/slimgel"},{"image":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/skinfix-velaro.webp?v=1793218146","width":719,"height":718,"title":"SkinFix - Cremă Anti-aging Colagen PDRN","price":"","oldPrice":"","badge":"Cel mai vândut","badgeBg":"#e9ff0e","badgeColor":"#000000","href":"https://velaro-shop.ro/products/skinfix-collagen"},{"image":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/novalift-velaro.webp?v=1793218412","width":499,"height":497,"title":"NovaLift - cremă anti-cearcăne și riduri","price":"","oldPrice":"","badge":"Cel mai vândut","badgeBg":"#e9ff0e","badgeColor":"#000000","href":"https://velaro-shop.ro/products/novalift"},{"image":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/Product_integration_into_202604211306_q60.webp?v=1792349221","width":1024,"height":1024,"title":"GoodSleep - Roll-on pentru un somn rapid și odihnitor","price":"69 lei","oldPrice":"139 lei","badge":"Produs TOP","badgeBg":"#e9ff0e","badgeColor":"#000000","href":"/goodsleep"},{"image":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/herbazen-product.jpg?v=1789490442","width":800,"height":800,"title":"HerbaZen - Pernuțe pentru picioare reci și obosite","price":"69 lei","oldPrice":"","badge":"Super ofertă","badgeBg":"#e9ff0e","badgeColor":"#000000","href":"/herbazen"},{"image":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/turmident-reduxio.webp?v=1793193054","width":500,"height":499,"title":"TURMIDENT - Pentru sângerări gingivale","price":"69 lei","oldPrice":"","badge":"Super reducere","badgeBg":"#e9ff0e","badgeColor":"#000000","href":"/turmident"},{"image":"https://cdn.shopify.com/s/files/1/0940/8787/2897/files/inel-magnifit-reduxio_1cd7f3f7-2114-433c-a2b6-3a46980ba592.webp?v=1793391787","width":358,"height":354,"title":"Inel MagniFit - inel magnetic pentru slăbit","price":"59 lei","oldPrice":"","badge":"Produs TOP","badgeBg":"#e9ff0e","badgeColor":"#000000","href":"/inel-magnifit"}],"columnsMobile":2,"columnsDesktop":4,"ratio":"1 / 1","buttonLabel":"Vezi produsul","buttonBg":"#ff7a00","buttonColor":"#ffffff","bg":"#ffffff","color":"#1a1a1a","radius":12,"label":"Produse"},{"type":"shared_footer","footerId":null}]$json$::jsonb, 'draft', true, 'wide'
from page_domains d
where d.hostname = 'comanda.reduxio.ro' and d.status in ('verified', 'active')
limit 1
on conflict do nothing;
